using System.Text.Json;
using System.Text.Json.Serialization;

namespace OpenCatasharpData.Models;

/// <summary>Noise generated by moving with a pocket or a worn armor section.</summary>
public sealed class CddaActivityNoise
{
    [JsonPropertyName("volume")]
    public decimal? Volume { get; set; }

    [JsonPropertyName("chance")]
    public decimal? Chance { get; set; }

    [JsonExtensionData]
    public Dictionary<string, JsonElement>? AdditionalProperties { get; set; }
}

/// <summary>Additional restrictions for a sealed pocket.</summary>
public sealed class CddaPocketSealedData
{
    [JsonPropertyName("spoil_multiplier")]
    public decimal? SpoilMultiplier { get; set; }

    [JsonExtensionData]
    public Dictionary<string, JsonElement>? AdditionalProperties { get; set; }
}
